(function() {
  const modals = document.querySelectorAll('.modal, [role="dialog"], .o_modal');
  for (let m of modals) {
    if (m.querySelector('heading')?.innerText?.includes('Cancel') || m.querySelector('h3')?.innerText?.includes('Cancel')) {
      return {
        innerHTML: m.innerHTML.substring(0, 2000),
        visible: m.offsetParent !== null,
        buttons: [...m.querySelectorAll('button, .btn, [role="button"]')].map(b => ({text: b.innerText, cl: b.className, disabled: b.disabled}))
      };
    }
  }
  return 'no modal found';
})()

[...document.querySelectorAll('.modal, [role="dialog"]')].map((m, i) => ({
  index: i,
  heading: m.querySelector('h1, h2, h3, heading, .modal-title')?.innerText || '',
  buttons: [...m.querySelectorAll('button')].map(b => ({text: b.innerText, display: window.getComputedStyle(b).display})),
