}))

(function() {
  const modal = document.querySelector('.modal.show, .modal:not([style*="display: none"])');
  if (!modal) return 'no visible modal';
  return {
    heading: modal.querySelector('h4, .modal-title')?.innerText,
    inputs: [...modal.querySelectorAll('input, textarea, select')].map(i => ({tag: i.tagName, name: i.name, type: i.type, required: i.required, value: i.value, placeholder: i.placeholder})),
    buttons: [...modal.querySelectorAll('button')].map(b => ({text: b.innerText.trim(), name: b.getAttribute('name'), disabled: b.disabled, visible: b.offsetParent !== null}))
  };
})()

(function() {
  const modal = document.querySelector('.modal.show, .modal:not([style*="display: none"])');
  if (!modal) return 'no visible modal';
  const btn = modal.querySelector('button[name="action_cancel"]');
  if (!btn) return 'no action_cancel button';
  return {
    btnText: btn.innerText.trim(),
    btnDisabled: btn.disabled,
    btnClasses: btn.className,
    modalHTML: modal.outerHTML.substring(0, 500)
  };
})()

(function() {
  const radios = [...document.querySelectorAll('.o_statusbar_status input[type="radio"], .o_statusbar_status [role="radio"]')];
  const statusText = document.querySelector('.o_statusbar_status')?.innerText;
  const breadcrumb = document.querySelector('.breadcrumb-item.active')?.innerText;
  return {statusText, breadcrumb, radioCount: radios.length};
})()

(function() {
  const modal = document.querySelector('.modal.show, .modal:not([style*="display: none"])');
  if (!modal) return 'no visible modal';
  const btn = modal.querySelector('button[name="action_cancel"]');
  if (!btn) return 'no action_cancel button';
  btn.click();
  return 'clicked action_cancel via JS';
})()

(function() {
  const statusText = document.querySelector('.o_statusbar_status')?.innerText;
  const breadcrumb = document.querySelector('.breadcrumb-item.active')?.innerText;
  const checked = document.querySelector('.o_statusbar_status input[checked], .o_statusbar_status .o_arrow_button_current')?.innerText;
  const allStatus = [...document.querySelectorAll('.o_statusbar_status .o_statusbar_status_item, .o_statusbar_status button, .o_statusbar_status label')].map(e => e.innerText.trim());
  return {statusText, breadcrumb, checked, allStatus};
})()
